import json
import sys
import time
import urllib.error
import urllib.request
from collections import Counter, defaultdict
from datetime import datetime, timezone

BASE = "http://localhost:8080"
RAW_DIR = "/tmp/recon"
token = None
request_log = Counter()


def log(*args):
    print(*args, file=sys.stderr, flush=True)


def raw_request(method, path, auth):
    req = urllib.request.Request(BASE + path, method=method)
    if auth and token:
        req.add_header("Authorization", "Bearer " + token)
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            body = resp.read()
            return resp.status, json.loads(body) if body else None, dict(resp.headers)
    except urllib.error.HTTPError as err:
        raw = err.read()
        try:
            body = json.loads(raw)
        except ValueError:
            body = raw.decode(errors="replace")
        return err.code, body, dict(err.headers)
    except urllib.error.URLError as err:
        return None, str(err.reason), {}


def retry_delay(status, body, headers, attempt):
    header = headers.get("Retry-After") if headers else None
    if header:
        try:
            return float(header)
        except ValueError:
            pass
    if isinstance(body, dict):
        for key in ("retry_after", "retry_after_seconds", "wait_seconds"):
            if key in body:
                return float(body[key])
    return min(2 ** attempt, 30)


def call(method, path, auth=False, max_attempts=40):
    """Returns (status, body). Retries on 401 (after refreshing the token), 429,
    5xx and network errors. Returns 404 (and other 4xx) to the caller without retry."""
    global token
    for attempt in range(max_attempts):
        status, body, headers = raw_request(method, path, auth)
        request_log[(path.split("?")[0].split("/")[1] if "/" in path else path, status)] += 1
        if status == 200:
            return status, body
        if status == 401 and auth:
            log(f"  401 on {path}: refreshing token")
            status_t, body_t, _ = raw_request("POST", "/token", False)
            if status_t == 200:
                token = body_t["token"]
                log(f"  new token issued")
            continue
        if status in (429, 503) or status is None or (status is not None and status >= 500):
            delay = retry_delay(status, body, headers, attempt)
            log(f"  {status} on {path} (attempt {attempt + 1}): {str(body)[:200]!r}; waiting {delay}s")
            time.sleep(delay)
            continue
        return status, body
    raise SystemExit(f"gave up on {path} after {max_attempts} attempts")


def get_token():
    global token
    status, body = call("POST", "/token")
    token = body["token"]
    log(f"token acquired: {token}")


def fetch_orders():
    pages = []
    page = 1
    while True:
        status, body = call("GET", f"/orders?page={page}", auth=True)
        if status != 200:
            raise SystemExit(f"orders page {page} returned {status}: {body}")
        pages.append({"page": page, "body": body})
        log(f"page {page}/{body['total_pages']}: {len(body['items'])} items, next={body['next']}")
        if page >= body["total_pages"]:
            break
        page += 1
    with open(f"{RAW_DIR}/pages.json", "w") as fh:
        json.dump(pages, fh)
    return pages


def fetch_customer(cache, cid):
    if cid not in cache:
        status, body = call("GET", f"/customers/{cid}", auth=True)
        cache[cid] = (status, body)
    return cache[cid]


def discounted_cents(amount, pct):
    # Half-up rounding of amount * (100 - pct) / 100 for non-negative integers.
    num = amount * (100 - pct)
    return (2 * num + 100) // 200


def parse_utc(ts):
    dt = datetime.fromisoformat(ts)
    if dt.tzinfo is None:
        raise ValueError(f"no offset in timestamp {ts!r}")
    return dt.astimezone(timezone.utc)


def main():
    get_token()
    pages = fetch_orders()

    listings = []
    for p in pages:
        listings.extend(p["body"]["items"])
    log(f"total listing rows: {len(listings)}")

    by_id = {}
    duplicates_skipped = 0
    conflicting_duplicates = []
    for row in listings:
        oid = row["id"]
        if oid in by_id:
            duplicates_skipped += 1
            if by_id[oid] != row:
                conflicting_duplicates.append((by_id[oid], row))
        else:
            by_id[oid] = row
    log(f"distinct order ids: {len(by_id)}; duplicate listings discarded: {duplicates_skipped}")
    log(f"duplicates whose content differs: {len(conflicting_duplicates)}")

    status_values = Counter(r["status"] for r in by_id.values())
    log(f"status values: {dict(status_values)}")
    odd_types = [r for r in by_id.values() if not isinstance(r["amount_cents"], int)]
    log(f"non-integer amount_cents rows: {len(odd_types)}")

    lo = datetime(2025, 3, 1, tzinfo=timezone.utc)
    hi = datetime(2025, 6, 1, tzinfo=timezone.utc)  # exclusive; covers all of 31 May UTC

    cache = {}
    total = 0
    count = 0
    by_region = defaultdict(int)
    unknown_customers = []
    bad_timestamps = []
    qualifying_ids = []
    for oid, row in by_id.items():
        if row["status"] != "shipped":
            continue
        try:
            when = parse_utc(row["placed_at"])
        except ValueError as err:
            bad_timestamps.append((oid, row["placed_at"], str(err)))
            continue
        if not (lo <= when < hi):
            continue
        status, cust = fetch_customer(cache, row["customer_id"])
        if status != 200:
            unknown_customers.append((oid, row["customer_id"], status))
            continue
        pct = cust["discount_pct"]
        if not isinstance(pct, int) or not 0 <= pct <= 100:
            raise SystemExit(f"unexpected discount_pct {pct!r} for {cust['id']}")
        amt = discounted_cents(row["amount_cents"], pct)
        total += amt
        count += 1
        by_region[cust["region"]] += amt
        qualifying_ids.append(oid)

    log(f"customers looked up: {len(cache)}")
    log(f"request outcomes: {dict(request_log)}")
    log(f"bad timestamps: {bad_timestamps}")
    log(f"unknown customers among qualifying orders: {unknown_customers}")
    log(f"conflicting duplicates: {conflicting_duplicates[:3]}")

    regions = {r: by_region.get(r, 0) for r in ("north", "south", "east", "west")}
    extra_regions = set(by_region) - set(regions)
    result = {
        "total_cents": total,
        "order_count": count,
        "duplicates_skipped": duplicates_skipped,
        "by_region": regions,
    }
    with open(f"{RAW_DIR}/result_candidate.json", "w") as fh:
        json.dump(result, fh, indent=2)
    with open(f"{RAW_DIR}/qualifying_ids.txt", "w") as fh:
        fh.write("\n".join(sorted(qualifying_ids)))
    log(f"extra regions not in template: {extra_regions}")
    log(json.dumps(result, indent=2))
    log(f"by_region sums to total: {sum(regions.values()) == total}")


if __name__ == "__main__":
    main()

